-- Load the monitor layout generated by nwg-displays.  nwg-displays owns
-- ~/.config/hypr/monitors.lua; this module deliberately leaves that file intact.
local home = os.getenv("HOME") or ""
local config = os.getenv("XDG_CONFIG_HOME") or (home .. "/.config")
local log = (hl and hl.print) or function() end

local function apply_file(path)
    local f = io.open(path, "r")
    if not f then return false end
    f:close()
    local ok, err = pcall(dofile, path)
    if not ok then
        log("[monitors] could not load " .. path .. ": " .. tostring(err))
        return false
    end
    log("[monitors] loaded " .. path)
    return true
end

local generated = config .. "/hypr/monitors.lua"
if not apply_file(generated) then
    -- Keep a safe single-display fallback if nwg-displays has not generated a layout yet.
    hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "1.25" })
end

-- Optional Quickshell monitor settings override selected outputs after nwg-displays.
-- This file is separate so nwg-displays can continue to own its generated layout.
apply_file(config .. "/hypr/monitors_custom.lua")
